const input = $input.first().json;
const weak = new Set(['le','la','les','de','du','des','et','chez','groupe','societe','entreprise']);
const norm = (value) => String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLocaleLowerCase('fr-FR').replace(/\bets\b/g, 'etablissements').replace(/\bcie\b/g, 'compagnie').replace(/\b(sa|sas|sasu|sarl|eurl|scop|association|ei|eirl)\b/g, ' ').replace(/[^a-z0-9 ]+/g, ' ').split(/\s+/).filter((t) => t && !weak.has(t)).join(' ');
const dice = (a, b) => { if (!a || !b) return 0; const grams = (s) => new Set([...Array(Math.max(s.length - 1, 1)).keys()].map((i) => s.slice(i, i + 2))); const ga = grams(a); const gb = grams(b); const inter = [...ga].filter((g) => gb.has(g)).length; return Math.round((2 * inter / Math.max(ga.size + gb.size, 1)) * 55); };
const locScore = (offer, c) => offer.postal_code && c.postal_code && String(offer.postal_code) === String(c.postal_code) ? 25 : norm(offer.city) && norm(offer.city) === norm(c.city) ? 18 : offer.department && c.postal_code && String(c.postal_code).startsWith(String(offer.department)) ? 10 : 0;
const rows = [];
for (const offer of input.offers) {
  const candidates = (input.candidates_by_offer_key[offer.offer_key] || []).slice(0, input.max_candidates);
  const ranked = candidates.map((c) => { const name_score = dice(norm(offer.declared_company_name || offer.company_name), norm(c.legal_name || c.trade_name)); const location_score = locScore(offer, c); const activity_score = offer.naf_code && c.naf_code && offer.naf_code === c.naf_code ? 10 : 0; const identifier_hint_score = c.siren || c.siret ? 10 : 0; const total_score = Math.min(100, name_score + location_score + activity_score + identifier_hint_score); return { candidate: c, score_dimensions: { name_score, location_score, activity_score, identifier_hint_score }, total_score }; }).sort((a, b) => b.total_score - a.total_score);
  const top = ranked[0] || null; const second = ranked[1] || null; const margin = top && second ? top.total_score - second.total_score : 100;
  let status = 'unresolved'; let reason = 'G8N_TOLERANT_NO_CREDIBLE_CANDIDATE';
  if (top && top.total_score >= input.thresholds.auto_match_min_score && margin >= input.thresholds.min_top_margin && top.score_dimensions.location_score > 0) { status = 'matched'; reason = 'G8N_TOLERANT_ACCENT_LEGAL_FORM'; }
  else if (top && top.total_score >= input.thresholds.ambiguous_min_score) { status = 'ambiguous'; reason = margin < input.thresholds.min_top_margin ? 'G8N_TOLERANT_CLOSE_SCORES' : 'G8N_TOLERANT_TYPO'; }
  rows.push({ offer_key: offer.offer_key, status, reason, top_margin: margin, ranked_candidates: ranked, review_required: status !== 'matched' });
}
return [{ json: { ...input, tolerant_match_results: rows } }];

const input = $input.first().json;
const now = new Date().toISOString();
const reviews = [];
const candidateRows = [];
for (const result of input.tolerant_match_results || []) {
  for (const [rank, item] of result.ranked_candidates.entries()) candidateRows.push({ candidate_key: `${result.offer_key}:${input.tolerant_match_version}:${rank + 1}`, offer_key: result.offer_key, match_rule_version: input.match_rule_version, rank: rank + 1, candidate_siren: item.candidate.siren || null, candidate_siret: item.candidate.siret || null, total_score: item.total_score, score_dimensions_json: JSON.stringify(item.score_dimensions), reason: result.reason, candidate_json: JSON.stringify(item.candidate), updated_at: now });
  if (result.review_required) reviews.push({ review_key: `${result.offer_key}:${input.tolerant_match_version}`, offer_key: result.offer_key, match_rule_version: input.match_rule_version, status: 'À vérifier', reason: result.reason, top_margin: result.top_margin, candidates_json: JSON.stringify(result.ranked_candidates), created_at: now, updated_at: now });
}
return [{ json: { ...input, company_match_candidate_upserts: candidateRows, company_match_review_upserts: reviews, next_step: 'Wire Data Table upserts locally; do not auto-validate weak cases.' } }];
